INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass alle Kunden in der IT dieselben Bedürfnisse haben. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Bedürfnisse variieren je nach Typ"}, {"text": "Ja", "correct": false, "because": "Zu pauschal"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich, wenn ich IT-Dienstleistungen für verschiedene Kunden anbiete?', 3, '[{"text": "Kundenspezifische Anpassung", "correct": true, "because": "Erfüllt individuelle Needs"}, {"text": "Einheitliche Lösungen", "correct": false, "because": "Ignoriert Unterschiede"}, {"text": "Schnellste Lieferung", "correct": false, "because": "Sekundär"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Kundengruppen gibt es in der IT-Dienstleistung?', 5, '[{"text": "Privatkunden", "correct": true, "because": "Individuen mit Einzelbedarf"}, {"text": "Unternehmenskunden", "correct": true, "because": "Firmen mit komplexen Anforderungen"}, {"text": "Hardware-Hersteller", "correct": false, "because": "Lieferanten, keine Kunden"}, {"text": "Marketingagenturen", "correct": false, "because": "Spezifische Branche"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Geschäftskunden brauchen oft skalierbare Lösungen. b) Privatkunden wollen immer teure Produkte.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Privatkunden variieren"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich, wenn ich IT-Support für verschiedene Kunden plane?', 4, '[{"text": "Kundenanforderungen", "correct": false, "because": "Bestimmen Dienst"}, {"text": "Budgetunterschiede", "correct": false, "because": "Beeinflussen Angebot"}, {"text": "Bürogestaltung", "correct": true, "because": "Kein Kundenfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob Geschäftskunden immer langfristige Verträge wollen?', 2, '[{"text": "Nein", "correct": true, "because": "Hängt vom Bedarf ab"}, {"text": "Ja", "correct": false, "because": "Nicht zwangsläufig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Ziel verfolge ich, wenn ich IT-Lösungen für Privatkunden anbiete?', 3, '[{"text": "Einfache Bedienung", "correct": true, "because": "Fördert Akzeptanz"}, {"text": "Komplexe Systeme", "correct": false, "because": "Überfordert oft"}, {"text": "Hohe Kosten", "correct": false, "because": "Nicht primär"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Faktoren unterscheiden Kunden in der IT?', 5, '[{"text": "Technisches Wissen", "correct": true, "because": "Beeinflusst Bedarf"}, {"text": "Budgetgröße", "correct": true, "because": "Bestimmt Lösung"}, {"text": "Büroausstattung", "correct": false, "because": "Kein Kundenmerkmal"}, {"text": "Firmenfarben", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Öffentliche Kunden brauchen oft Compliance. b) Alle Kunden wollen Open-Source. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Open-Source nicht universell"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht, um IT-Dienste für verschiedene Kunden anzubieten?', 4, '[{"text": "Flexibilität", "correct": false, "because": "Passt Angebote an"}, {"text": "Kundenanalyse", "correct": false, "because": "Erkennt Bedarf"}, {"text": "Einheitsdesign", "correct": true, "because": "Ignoriert Unterschiede"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Sind öffentliche Kunden immer budgetbeschränkt?', 2, '[{"text": "Nein", "correct": true, "because": "Variiert je nach Institution"}, {"text": "Ja", "correct": false, "because": "Nicht zwangsläufig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet eine Anpassung an Geschäftskunden?', 4, '[{"text": "Langfristige Bindung", "correct": true, "because": "Erfüllt spezifische Needs"}, {"text": "Höhere Umsätze", "correct": true, "because": "Oft größere Projekte"}, {"text": "Schnellere Lieferung", "correct": false, "because": "Kein direkter Vorteil"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass Privatkunden nur günstige Lösungen wollen. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Qualität oft wichtig"}, {"text": "Ja", "correct": false, "because": "Nicht immer preisorientiert"}]'),
('00000000-0000-0000-0000-000000000000', 'Was wähle ich, um IT-Support für öffentliche Kunden zu optimieren?', 3, '[{"text": "Regelkonformität", "correct": true, "because": "Erfüllt Vorgaben"}, {"text": "Teure Hardware", "correct": false, "because": "Nicht primär"}, {"text": "Bunte Interfaces", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Geschäftskunden brauchen oft Supportverträge. b) Privatkunden wollen immer Cloud-Lösungen.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Cloud nicht universell"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Aspekte berücksichtige ich bei IT-Lösungen für verschiedene Kunden?', 5, '[{"text": "Technische Anforderungen", "correct": true, "because": "Bestimmen Lösung"}, {"text": "Zahlungsbereitschaft", "correct": true, "because": "Beeinflusst Angebot"}, {"text": "Bürogröße", "correct": false, "because": "Sekundär"}, {"text": "Firmenlogo", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist unwichtig, wenn ich IT-Dienste für Privatkunden anbiete?', 3, '[{"text": "Einfachheit", "correct": false, "because": "Fördert Nutzung"}, {"text": "Kosten", "correct": false, "because": "Entscheidend für Akzeptanz"}, {"text": "Markenimage", "correct": true, "because": "Weniger relevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Brauchen Geschäftskunden immer maßgeschneiderte Lösungen?', 3, '[{"text": "Nein", "correct": true, "because": "Standardlösungen oft ausreichend"}, {"text": "Ja", "correct": false, "because": "Nicht zwangsläufig"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob öffentliche Kunden oft langfristige Projekte haben?', 2, '[{"text": "Ja", "correct": true, "because": "Häufig große Ausschreibungen"}, {"text": "Nein", "correct": false, "because": "Tendenz zu Langfristigkeit"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Merkmal ist entscheidend, wenn ich IT für Geschäftskunden anbiete?', 4, '[{"text": "Skalierbarkeit", "correct": true, "because": "Passt sich Wachstum an"}, {"text": "Günstigster Preis", "correct": false, "because": "Qualität oft wichtiger"}, {"text": "Bunte Optik", "correct": false, "because": "Irrelevant"}]');
